import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.BxrwG5q5.js";const u=JSON.parse('{"title":"Segments","description":"","frontmatter":{},"headers":[],"relativePath":"features/segments.md","filePath":"features/segments.md"}'),n={name:"features/segments.md"};function o(r,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="segments" tabindex="-1">Segments <a class="header-anchor" href="#segments" aria-label="Permalink to &quot;Segments&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/guide/scopes.html">Configuration Scopes</a> · <a href="/config/features/rollouts.html">Percentage Rollouts</a></p></blockquote><p>Segments are reusable audience groups that you can target across multiple feature flags and configs. Instead of duplicating conditions like &quot;plan equals enterprise AND country in US, UK&quot; on every flag, define it once as a segment and reference it everywhere. See <a href="/config/guide/scopes.html">Configuration Scopes</a> for how segments fit into the broader evaluation model.</p><h2 id="creating-a-segment" tabindex="-1">Creating a Segment <a class="header-anchor" href="#creating-a-segment" aria-label="Permalink to &quot;Creating a Segment&quot;">​</a></h2><ol><li>Go to <strong>Segments</strong> in the portal navigation</li><li>Click <strong>Create Segment</strong></li><li>Give it a name (e.g., &quot;Enterprise Users&quot;, &quot;Beta Testers&quot;)</li><li>Define conditions using attributes: <ul><li><code>plan</code> equals <code>enterprise</code></li><li><code>country</code> in_list <code>US, UK, DE</code></li><li><code>email</code> ends_with <code>@company.com</code></li></ul></li></ol><h2 id="condition-logic" tabindex="-1">Condition Logic <a class="header-anchor" href="#condition-logic" aria-label="Permalink to &quot;Condition Logic&quot;">​</a></h2><p>Segments use <strong>DNF (Disjunctive Normal Form)</strong>:</p><ul><li>Conditions within a group are <strong>AND</strong> (all must match)</li><li>Groups are connected by <strong>OR</strong> (any group matching is sufficient)</li></ul><p><strong>Example:</strong> &quot;Enterprise users in US/UK OR anyone with a @company.com email&quot;</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Group 1: plan equals &quot;enterprise&quot; AND country in_list &quot;US,UK&quot;</span></span>
<span class="line"><span>   OR</span></span>
<span class="line"><span>Group 2: email ends_with &quot;@company.com&quot;</span></span></code></pre></div><h2 id="using-segments-in-targeting" tabindex="-1">Using Segments in Targeting <a class="header-anchor" href="#using-segments-in-targeting" aria-label="Permalink to &quot;Using Segments in Targeting&quot;">​</a></h2><p>When creating a <a href="/config/features/targeting.html">targeting rule</a> on a config or feature flag:</p><ol><li>Click <strong>Target Segment</strong> (primary action)</li><li>Click the segment badges to select them</li><li>Set the value to serve for users in those segments</li><li>Multiple segments use OR logic — user in ANY selected segment gets the value</li></ol><h2 id="supported-operators" tabindex="-1">Supported Operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>equals</code></td><td>Exact match</td><td><code>plan</code> equals <code>&quot;pro&quot;</code></td></tr><tr><td><code>not_equals</code></td><td>Does not match</td><td><code>status</code> not_equals <code>&quot;banned&quot;</code></td></tr><tr><td><code>contains</code></td><td>Substring match</td><td><code>email</code> contains <code>&quot;@gmail&quot;</code></td></tr><tr><td><code>starts_with</code></td><td>Prefix match</td><td><code>user_id</code> starts_with <code>&quot;usr_&quot;</code></td></tr><tr><td><code>ends_with</code></td><td>Suffix match</td><td><code>email</code> ends_with <code>&quot;.edu&quot;</code></td></tr><tr><td><code>in_list</code></td><td>Any in comma-separated list</td><td><code>country</code> in_list <code>&quot;US,UK,DE&quot;</code></td></tr><tr><td><code>not_in_list</code></td><td>None in list</td><td><code>plan</code> not_in_list <code>&quot;free,trial&quot;</code></td></tr><tr><td><code>greater_than</code></td><td>Numeric greater</td><td><code>age</code> greater_than <code>18</code></td></tr><tr><td><code>less_than</code></td><td>Numeric less</td><td><code>login_count</code> less_than <code>5</code></td></tr><tr><td><code>regex_match</code></td><td>Regular expression</td><td><code>email</code> regex_match <code>&quot;.*@corp\\\\.com$&quot;</code></td></tr></tbody></table><h2 id="segment-usage-tracking" tabindex="-1">Segment Usage Tracking <a class="header-anchor" href="#segment-usage-tracking" aria-label="Permalink to &quot;Segment Usage Tracking&quot;">​</a></h2><p>The portal shows which configs reference each segment. This helps you understand the impact before modifying or deleting a segment.</p><h2 id="how-segments-work-with-api-keys" tabindex="-1">How Segments Work with API Keys <a class="header-anchor" href="#how-segments-work-with-api-keys" aria-label="Permalink to &quot;How Segments Work with API Keys&quot;">​</a></h2><ul><li><strong>Client keys (cid_):</strong> The API evaluates segment membership server-side. Your segment conditions are never exposed to the browser.</li><li><strong>Server keys (svr_):</strong> Segment definitions are included in the API response for local evaluation by the SDK.</li></ul><h2 id="segments-and-autocontext" tabindex="-1">Segments and autoContext <a class="header-anchor" href="#segments-and-autocontext" aria-label="Permalink to &quot;Segments and autoContext&quot;">​</a></h2><p>When you pass attributes via <code>autoContext()</code>, they are automatically available for segment evaluation:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> flags</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> initConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  clientId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cid_xxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  context: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">autoContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    userId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user_123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    plan: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enterprise&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    country: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;US&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>If you have a segment defined as <code>plan equals &quot;enterprise&quot;</code>, users whose context includes <code>plan: &quot;enterprise&quot;</code> will automatically match that segment. The SDK sends context attributes to the API, which evaluates segment membership server-side.</p><p><strong>Auto-detected attributes</strong> (browser, OS, device, locale, timezone) are also available for segment conditions — you can create segments like &quot;Mobile Users&quot; with <code>device equals &quot;mobile&quot;</code> without any extra configuration.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Use segments in targeting rules to serve different values per audience</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — How context, segments, and scopes interact during evaluation</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Combine segments with gradual rollouts for targeted releases</li><li><a href="/config/features/export.html">Export</a> — Bulk export includes segment definitions</li><li><a href="/config/api/">SDK Reference</a> — Passing context attributes for segment evaluation</li></ul>`,26)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
